configuration.styles:
/* ======= Common badge styling ======= */
.badge, .badge-status, .status {
    border-radius: 4px;
    padding: 2px 6px;
    font-size: 13px;
    transition: background-color 0.2s, color 0.2s;
}

/* ======= PASS badges ======= */
.badge.log.pass,
.badge-status.pass,
.status.pass,
.status.pass i {
    color: #28a745 !important;   /* green text/icons */
    background-color: #e6f4ea;   /* light green background for visibility */
}

/* ======= IMAGE badges ======= */
span.badge[data-tooltip="image"],
span.badge-default[data-tooltip="image"] {
    background-color: #28a745 !important;
    color: #fff !important;
    border-radius: 4px;
    padding: 2px 6px;
}

/* Add camera icon before IMAGE badge */
span.badge[data-tooltip="image"]::before,
span.badge-default[data-tooltip="image"]::before {
    content: "📷 ";
    font-size: 13px;
    margin-right: 2px;
}

/* Optional hover effect for all badges */
.badge:hover, .badge-status:hover, .status:hover {
    opacity: 0.85;
}
